const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf4f7fb);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const keyLight = new THREE.DirectionalLight(0xffffff, 1.35);
keyLight.position.set(6, 10, 8);
keyLight.castShadow = true;
keyLight.shadow.mapSize.width = 2048;
keyLight.shadow.mapSize.height = 2048;
keyLight.shadow.bias = -0.0001;

const fillLight = new THREE.DirectionalLight(0xbfd7ff, 0.55);
fillLight.position.set(-7, 4, 5);

const rimLight = new THREE.PointLight(0xaad6ff, 0.45, 22);
rimLight.position.set(-4, 3, -5);

scene.add(new THREE.AmbientLight(0x7f8aa6, 0.32), keyLight, fillLight, rimLight);

const floor = new THREE.Mesh(
  new THREE.CircleGeometry(15, 96),
  new THREE.MeshStandardMaterial({ color: 0xe6ecf5, roughness: 0.92, metalness: 0.02 })
);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -2;
floor.receiveShadow = true;
scene.add(floor);

const heroGroup = new THREE.Group();
scene.add(heroGroup);

const steelMaterial = new THREE.MeshStandardMaterial({
  color: 0x8899a6,
  roughness: 0.3,
  metalness: 0.8,
});

const copperMaterial = new THREE.MeshStandardMaterial({
  color: 0xb87333,
  roughness: 0.4,
  metalness: 0.9,
});

const waterMaterial = new THREE.MeshPhysicalMaterial({
  color: 0x4fc3f7,
  transmission: 0.6,
  opacity: 0.8,
  roughness: 0.1,
  metalness: 0,
  transparent: true,
  thickness: 2,
});

const electricityMaterial = new THREE.MeshStandardMaterial({
  color: 0xffeb3b,
  emissive: 0xffd700,
  emissiveIntensity: 2,
  roughness: 0.2,
});

const concreteMaterial = new THREE.MeshStandardMaterial({
  color: 0x9e9e9e,
  roughness: 0.9,
  metalness: 0.1,
});

const housingGeo = new THREE.CylinderGeometry(2, 2, 4, 64, 4);
const housing = new THREE.Mesh(housingGeo, steelMaterial);
housing.rotation.z = Math.PI / 2;
housing.position.x = -1;
housing.castShadow = true;
housing.receiveShadow = true;
heroGroup.add(housing);

const waterGeo = new THREE.CylinderGeometry(1.6, 1.6, 3.8, 32, 1);
const waterFlow = new THREE.Mesh(waterGeo, waterMaterial);
waterFlow.rotation.z = Math.PI / 2;
waterFlow.position.x = -1;
heroGroup.add(waterFlow);

const bladeGroup = new THREE.Group();
bladeGroup.position.x = -1;
heroGroup.add(bladeGroup);

for (let i = 0; i < 8; i++) {
  const bladeGeo = new THREE.BoxGeometry(0.2, 1.8, 0.1);
  const blade = new THREE.Mesh(bladeGeo, steelMaterial);
  blade.position.y = 0.9;

  const pivot = new THREE.Group();
  pivot.rotation.z = (i / 8) * Math.PI * 2;
  pivot.add(blade);
  bladeGroup.add(pivot);
}

const statorGroup = new THREE.Group();
statorGroup.position.x = 0.5;
heroGroup.add(statorGroup);

for (let i = 0; i < 12; i++) {
  const coilGeo = new THREE.TorusGeometry(1.4, 0.15, 16, 32);
  const coil = new THREE.Mesh(coilGeo, copperMaterial);
  coil.rotation.y = Math.PI / 2;
  coil.position.x = -0.8 + (i * 0.15);
  coil.castShadow = true;
  statorGroup.add(coil);
}

const coreGeo = new THREE.CylinderGeometry(0.8, 0.8, 3, 32);
const coreMaterial = new THREE.MeshStandardMaterial({
  color: 0x333333,
  roughness: 0.5,
  metalness: 0.7,
});
const core = new THREE.Mesh(coreGeo, coreMaterial);
core.rotation.z = Math.PI / 2;
core.position.x = 0.5;
heroGroup.add(core);

const supportGeo = new THREE.BoxGeometry(4, 0.5, 3);
const support = new THREE.Mesh(supportGeo, concreteMaterial);
support.position.y = -2.25;
support.castShadow = true;
support.receiveShadow = true;
heroGroup.add(support);

const towerGroup = new THREE.Group();
towerGroup.position.set(6, -1, 0);
heroGroup.add(towerGroup);

const towerBaseGeo = new THREE.CylinderGeometry(0.3, 0.8, 4, 4);
const tower = new THREE.Mesh(towerBaseGeo, steelMaterial);
tower.position.y = 2;
tower.castShadow = true;
towerGroup.add(tower);

const wirePoints = [];
for (let i = 0; i <= 20; i++) {
  const t = i / 20;
  const x = 2 + t * 4;
  const y = 1.5 + Math.sin(t * Math.PI) * 0.5;
  const z = Math.sin(t * Math.PI * 2) * 0.2;
  wirePoints.push(new THREE.Vector3(x, y, z));
}
const wireCurve = new THREE.CatmullRomCurve3(wirePoints);
const wireGeo = new THREE.TubeGeometry(wireCurve, 64, 0.03, 8, false);
const wireMaterial = new THREE.MeshStandardMaterial({ color: 0x444444, metalness: 0.6, roughness: 0.4 });
const wire = new THREE.Mesh(wireGeo, wireMaterial);
heroGroup.add(wire);

const insulatorGeo = new THREE.CylinderGeometry(0.1, 0.15, 0.6, 8);
const insulator = new THREE.Mesh(insulatorGeo, new THREE.MeshStandardMaterial({ color: 0xffffff }));
insulator.position.y = 4;
towerGroup.add(insulator);

const cityGroup = new THREE.Group();
cityGroup.position.set(10, -2, -2);
heroGroup.add(cityGroup);

const buildingGeo = new THREE.BoxGeometry(2, 3, 2);
const windowMaterial = new THREE.MeshStandardMaterial({
  color: 0xffeb3b,
  emissive: 0xffaa00,
  emissiveIntensity: 0.5,
});

for (let i = 0; i < 3; i++) {
  const building = new THREE.Mesh(
    new THREE.BoxGeometry(1.5 - i*0.2, 2 + Math.random(), 1.5),
    new THREE.MeshStandardMaterial({ color: 0xcccccc, roughness: 0.8 })
  );
  building.position.set(i * 1.2, 0, i * 0.5);
  building.castShadow = true;
  cityGroup.add(building);

  for (let j = 0; j < 3; j++) {
    const win = new THREE.Mesh(new THREE.PlaneGeometry(0.3, 0.3), windowMaterial);
    win.position.set(i * 1.2, 0.5 + j * 0.4, i * 0.5 + 0.76);
    cityGroup.add(win);
  }
}

const particleCount = 30;
const particles = new THREE.InstancedMesh(
  new THREE.SphereGeometry(0.08, 16, 16),
  electricityMaterial,
  particleCount
);
heroGroup.add(particles);

const dummy = new THREE.Object3D();

const sparkGeo = new THREE.BufferGeometry();
const sparkVertices = [];
for (let i = 0; i < 20; i++) {
  sparkVertices.push(
    0.5 + Math.random() * 1,
    Math.random() * 2 - 1,
    Math.random() * 0.5 - 0.25
  );
}
sparkGeo.setAttribute('position', new THREE.Float32BufferAttribute(sparkVertices, 3));
const sparkLine = new THREE.LineSegments(
  sparkGeo,
  new THREE.LineBasicMaterial({ color: 0x4fc3f7, transparent: true, opacity: 0.6 })
);
heroGroup.add(sparkLine);

const glowGeo = new THREE.SphereGeometry(1.8, 32, 32);
const glowMat = new THREE.MeshBasicMaterial({
  color: 0x4fc3f7,
  transparent: true,
  opacity: 0.1,
  side: THREE.BackSide,
});
const glow = new THREE.Mesh(glowGeo, glowMat);
glow.position.x = 0.5;
heroGroup.add(glow);

camera.position.set(8, 4, 8);
camera.lookAt(2, 0, 0);

const controls = new THREE.OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(2, 0, 0);

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  bladeGroup.rotation.x = t * 2;
  core.rotation.x = t * 2;

  waterFlow.scale.x = 1 + Math.sin(t * 10) * 0.02;

  for (let i = 0; i < particleCount; i++) {
    let pos = (t * 2 + i * 0.1) % 1;
    const point = wireCurve.getPoint(pos);
    dummy.position.copy(point);
    dummy.scale.setScalar(1 - pos * 0.5);
    dummy.updateMatrix();
    particles.setMatrixAt(i, dummy.matrix);
  }
  particles.instanceMatrix.needsUpdate = true;

  const positions = sparkLine.geometry.attributes.position.array;
  for (let i = 0; i < positions.length; i += 3) {
    if (Math.random() > 0.95) {
      positions[i] = 0.5 + Math.random() * 1;
      positions[i + 1] = Math.random() * 2 - 1;
      positions[i + 2] = Math.random() * 0.5 - 0.25;
    }
  }
  sparkLine.geometry.attributes.position.needsUpdate = true;
  sparkLine.material.opacity = 0.3 + Math.sin(t * 15) * 0.3;

  cityGroup.children.forEach((child, idx) => {
    if (child.material.emissive && child.material.emissive.r > 0) {
      child.material.emissiveIntensity = 0.5 + Math.sin(t * 3 + idx) * 0.2;
    }
  });

  rimLight.intensity = 0.35 + Math.sin(t * 1.2) * 0.08;

  glow.scale.setScalar(1 + Math.sin(t * 4) * 0.05);
  glow.material.opacity = 0.08 + Math.sin(t * 2) * 0.03;

  controls.update();
  renderer.render(scene, camera);
}

animate();

